-- DHAULAGIRI CIRCUIT TREK
('Dhaulagiri Circuit Trek','dhaulagiri-circuit-trek','A challenging camping trek around the world''s 7th highest mountain through dramatic glacier terrain.','The Dhaulagiri Circuit Trek is a true wilderness expedition that circles Mt. Dhaulagiri (8,167m), the world''s 7th highest mountain. This is a camping-only trek that crosses two high passes — the French Pass (5,360m) and the Dhampus Pass (5,246m) — and traverses the massive Dhaulagiri Glacier. The trek offers some of the most dramatic mountain scenery in Nepal, with close-up views of Dhaulagiri''s towering ice walls, the famous "Hidden Valley," and panoramic views of the Annapurna and Nilgiri ranges. This is a trek for experienced trekkers seeking a genuine wilderness challenge.','https://images.pexels.com/photos/417173/pexels-photo-417173.jpeg?auto=compress&cs=tinysrgb&w=1600','16 Days','Expert','$2,500','Trek',32,
'[{"day":1,"title":"Arrive in Kathmandu","description":"Arrival and expedition briefing."},{"day":2,"title":"Drive to Beni","description":"Scenic drive from Kathmandu to Beni (830m)."},{"day":3,"title":"Beni to Dharapani","description":"Begin trekking through traditional villages."},{"day":4,"title":"Dharapani to Muri","description":"Walk through subtropical forests."},{"day":5,"title":"Muri to Boghara","description":"Enter alpine terrain."},{"day":6,"title":"Boghara to Dobang","description":"Trek through rhododendron forests."},{"day":7,"title":"Dobang to Sallaghari","description":"Approach the Dhaulagiri base camp area."},{"day":8,"title":"Sallaghari to Dhaulagiri BC","description":"Arrive at Dhaulagiri Base Camp (4,700m)."},{"day":9,"title":"Acclimatization at BC","description":"Rest and explore the base camp area."},{"day":10,"title":"Cross French Pass","description":"Cross French Pass (5,360m). Enter Hidden Valley."},{"day":11,"title":"Cross Dhampus Pass","description":"Cross Dhampus Pass (5,246m). Descend."},{"day":12,"title":"Trek to Marpha","description":"Descend to the apple-growing village of Marpha."},{"day":13,"title":"Explore Marpha","description":"Rest day in Marpha. Apple brandy tasting."},{"day":14,"title":"Drive to Pokhara","description":"Scenic drive from Jomsom to Pokhara."},{"day":15,"title":"Drive to Kathmandu","description":"Return to Kathmandu."},{"day":16,"title":"Departure","description":"Airport transfer."}]'::jsonb,
'["All ground transport","Hotel in Kathmandu","Camping equipment (tents, mattresses, kitchen)","All meals on trek","English-speaking guide","Cook and kitchen staff","Porter service","Dhaulagiri Conservation Area permit","TIMS card","Satellite phone"]'::jsonb,
'["International flights","Nepal visa","Travel insurance","Personal clothing and sleeping bag","Tips","Alcoholic drinks"]'::jsonb,
'["Trek around the world''s 7th highest mountain (8,167m)","Cross French Pass (5,360m) and Dhampus Pass (5,246m)","Explore the famous Hidden Valley","Camping expedition through Dhaulagiri Glacier","Views of Dhaulagiri, Annapurna, and Nilgiri ranges","One of Nepal''s most challenging wilderness treks"]'::jsonb),

-- RARA LAKE TREK (Far West)
('Rara Lake Trek','rara-lake-trek','A journey to Nepal''s largest lake in the remote far-west, surrounded by pristine forests and alpine meadows.','The Rara Lake Trek takes you to Rara Lake (2,990m), Nepal''s largest lake, located in the remote far-western region of the country. The lake is the centerpiece of Rara National Park, a pristine wilderness of pine, juniper, and rhododendron forests. The trek offers stunning views of the surrounding hills and distant Himalayan peaks including Saipal (7,031m). The region is home to diverse wildlife including musk deer, Himalayan black bears, and over 200 species of birds. The remote location means very few trekkers make it here, offering a truly off-the-beaten-path experience.','https://images.pexels.com/photos/2387871/pexels-photo-2387871.jpeg?auto=compress&cs=tinysrgb&w=1600','12 Days','Moderate','$1,400','Trek',33,
'[{"day":1,"title":"Arrive in Kathmandu","description":"Arrival and briefing."},{"day":2,"title":"Fly to Nepalgunj","description":"Domestic flight to Nepalgunj."},{"day":3,"title":"Fly to Jumla, Trek to Danphe Lagna","description":"Flight to Jumla. Begin trekking."},{"day":4,"title":"Danphe Lagna to Chautha","description":"Trek through pine forests and traditional villages."},{"day":5,"title":"Chautha to Dhotu","description":"Continue through beautiful landscapes."},{"day":6,"title":"Dhotu to Rara Lake","description":"Arrive at the stunning Rara Lake (2,990m)."},{"day":7,"title":"Explore Rara Lake","description":"Full day exploring the lake, national park, and surrounding hills."},{"day":8,"title":"Rara Lake to Sinja","description":"Trek to the historic Sinja Valley."},{"day":9,"title":"Explore Sinja","description":"Khas kingdom ruins and ancient inscriptions."},{"day":10,"title":"Sinja to Jumla","description":"Return trek to Jumla."},{"day":11,"title":"Fly to Kathmandu","description":"Return via Nepalgunj."},{"day":12,"title":"Departure","description":"Airport transfer."}]'::jsonb,
'["Airport transfers","All domestic flights","Hotel in Kathmandu","Teahouse accommodation","All meals on trek","English-speaking guide","Porter service","Rara National Park permit","TIMS card"]'::jsonb,
'["International flights","Nepal visa","Travel insurance","Personal gear","Tips","Alcoholic drinks"]'::jsonb,
'["Rara Lake — Nepal''s largest and most beautiful lake","Rara National Park — pristine wilderness","Remote far-west region — very few trekkers","Views of Saipal Himal (7,031m)","Historic Sinja Valley — ancient Khas kingdom","Over 200 species of birds and diverse wildlife"]'::jsonb),

-- GANESH HIMAL BASE CAMP TREK
('Ganesh Himal Base Camp Trek','ganesh-himal-base-camp','A cultural trek through the Ruby Valley to the base of sacred Ganesh Himal with stunning mountain panoramas.','The Ganesh Himal Base Camp Trek is a wonderful cultural trek through the Ruby Valley region, named for the precious stones found here. The trek offers spectacular views of the Ganesh Himal range, including Yangra (7,422m), the highest peak in the range. The trail passes through traditional Tamang and Buddhist villages, terraced fields, and rhododendron forests. You''ll visit hot springs at Tatopani, cross suspension bridges, and experience the rich cultural heritage of the region. This is a relatively new trekking route that remains uncrowded and authentic.','https://images.pexels.com/photos/2387873/pexels-photo-2387873.jpeg?auto=compress&cs=tinysrgb&w=1600','17 Days','Moderate','$1,550','Trek',34,
'[{"day":1,"title":"Arrive in Kathmandu","description":"Arrival and briefing."},{"day":2,"title":"Drive to Syabrubesi","description":"7-8 hour drive to Syabrubesi."},{"day":3,"title":"Syabrubesi to Gatlang","description":"Trek through Tamang villages to Gatlang."},{"day":4,"title":"Gatlang to Somdang","description":"Ascend through forests with mountain views."},{"day":5,"title":"Somdang to Pansing Kharka","description":"Trek to the base of Ganesh Himal."},{"day":6,"title":"Ganesh Himal Base Camp","description":"Hike to Ganesh Himal Base Camp (4,200m). Return to Pansing."},{"day":7,"title":"Pansing to Somdang","description":"Descend back through the valley."},{"day":8,"title":"Somdang to Tipling","description":"Trek through the Ruby Valley. Visit local gem mines."},{"day":9,"title":"Tipling to Shertung","description":"Continue through traditional villages."},{"day":10,"title":"Shertung to Jharlang","description":"Cross ridges with panoramic views."},{"day":11,"title":"Jharlang to Darkha","description":"Descend through forests and terraced fields."},{"day":12,"title":"Darkha to Malekhu","description":"Final trekking day to the road."},{"day":13,"title":"Drive to Kathmandu","description":"Return drive."}]'::jsonb,
'["Airport transfers","Private ground transport","Hotel in Kathmandu","Teahouse accommodation","All meals on trek","English-speaking guide","Porter service","National Park permit","TIMS card"]'::jsonb,
'["International flights","Nepal visa","Travel insurance","Personal gear","Tips","Alcoholic drinks"]'::jsonb,
'["Ganesh Himal views including Yangra (7,422m)","Ruby Valley — named for precious gemstones","Rich Tamang culture and Buddhist traditions","Hot springs and traditional villages","Relatively new route — few trekkers","Spectacular mountain panoramas"]'::jsonb)

) AS v(title, slug, description, long_description, image_url, duration, difficulty, price, category, sort_order, itinerary, includes, excludes, highlights)
WHERE NOT EXISTS (SELECT 1 FROM public.adventures WHERE slug = v.slug);


