    long_description = 'The Langtang Valley is often called the "Valley of Glaciers" and offers some of the most accessible high-altitude trekking in Nepal. Just a 7-hour drive from Kathmandu, the trail leads through dense forests of bamboo and rhododendron, past cascading waterfalls, to the stunning Langtang Valley. The region was devastated by the 2015 earthquake, but the recovery has been remarkable — new lodges, rebuilt monasteries, and the famous Langtang cheese factory are all operating again. Highlights include the serene Kyanjin Gompa monastery, views of Langtang Lirung (7,227m), and the challenging climb to Tserko Ri (4,985m) for panoramic views of 20+ Himalayan peaks.',
    highlights = '["Explore the beautiful Langtang Valley — the Valley of Glaciers","Trek through bamboo and rhododendron forests","Visit Kyanjin Gompa monastery and cheese factory","Climb Tserko Ri (4,985m) for panoramic views","No flight needed — 7 hour drive from Kathmandu","Remarkable post-earthquake recovery story"]'::jsonb,
    price = '$899',
    includes = '["Private ground transport Kathmandu-Syabrubesi","Teahouse accommodation","All meals on trek","English-speaking guide","Porter service","Langtang National Park permit","TIMS card","First aid kit"]'::jsonb
  WHERE slug = 'langtang-valley';

